answer.python_code:
levels = sorted(set(r['z'] for r in rows))
total = sum(r['weight'] for r in rows)
mass = {(z, x): sum(r['weight'] for r in rows if r['z'] == z and r['x'] == x) for z in levels for x in (0, 1)}
risk = {(z, x): Fraction(sum(r['weight'] * r['y'] for r in rows if r['z'] == z and r['x'] == x), mass[z, x]) for z in levels for x in (0, 1)}
estimate = sum(Fraction(mass[z, 0] + mass[z, 1], total) * (risk[z, 1] - risk[z, 0]) for z in levels)
